(()=>{
let pane=null,divider=null,sheet='diff',page=0,mode='excel';
const rows=window.InventoryReconciliationRows,main=document.querySelector('.app>.main>main'),safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function close(){pane?.remove();divider?.remove();pane=divider=null;document.body.classList.remove('reconciliation-open','reconciliation-expanded');main.style.removeProperty('--recon-panel-width')}
function data(){return sheet==='erp'?rows.map(r=>r.slice(0,6)):sheet==='wms'?rows.map(r=>r.slice(0,5).concat(r[6])):rows.filter(r=>r[5]!==r[6]).map(r=>r.concat(r[6]-r[5],'数量不一致'))}
function headers(){const base=['交易参考','物料编码','物料描述','仓库','单位'];return base.concat(sheet==='erp'?['ERP数量']:sheet==='wms'?['WMS数量']:['ERP数量','WMS数量','数量差异','对账结果'])}
function excel(){const h=headers(),r=data(),display=r.slice(page*15,page*15+15),letters=h.map((_,i)=>String.fromCharCode(65+i));while(display.length<15)display.push(h.map(()=>''));pane.querySelector('.recon-content').innerHTML='<div class="excel-ribbon"><span>开始</span><span>插入</span><span>数据</span><span>视图</span><small>3个工作表 · ERP / WMS</small></div><div class="excel-formula"><span data-cell>A1</span><b>ƒx</b><output data-formula>'+safe(h[0])+'</output></div><div class="recon-grid"><table class="online-sheet" aria-label="'+({erp:'ERP原始数据',wms:'WMS原始数据',diff:'差异对比'})[sheet]+'"><thead><tr><th></th>'+letters.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody><tr><th>1</th>'+h.map((x,i)=>'<td class="sheet-header" data-address="'+letters[i]+'1">'+x+'</td>').join('')+'</tr>'+display.map((row,i)=>'<tr><th>'+(page*15+i+2)+'</th>'+row.map((x,j)=>'<td data-address="'+letters[j]+(page*15+i+2)+'"'+(sheet==='diff'&&i<2?' class="recon-mismatch"':'')+'>'+safe(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="excel-sheet-tabs" role="tablist" aria-label="对账Excel工作表">'+[['erp','ERP原始数据'],['wms','WMS原始数据'],['diff','差异对比']].map(([id,name])=>'<button role="tab" aria-selected="'+(id===sheet)+'" data-sheet="'+id+'">'+name+'</button>').join('')+'<span>'+r.length+' 条</span></div><div class="recon-status"><span>就绪 · 示例数据</span><div><button data-prev '+(!page?'disabled':'')+'>上一页</button><span>第 '+(page+1)+' / '+Math.max(1,Math.ceil(r.length/15))+' 页</span><button data-next '+((page+1)*15>=r.length?'disabled':'')+'>下一页</button></div><span>100%</span></div>';
pane.querySelectorAll('[data-sheet]').forEach(b=>b.onclick=()=>{sheet=b.dataset.sheet;page=0;excel()});pane.querySelector('[data-prev]').onclick=()=>{page--;excel()};pane.querySelector('[data-next]').onclick=()=>{page++;excel()};pane.querySelectorAll('[data-address]').forEach(td=>td.onclick=()=>{pane.querySelector('.selected-cell')?.classList.remove('selected-cell');td.classList.add('selected-cell');pane.querySelector('[data-cell]').textContent=td.dataset.address;pane.querySelector('[data-formula]').textContent=td.textContent})}
function details(){pane.querySelector('.recon-content').innerHTML='<div class="recon-business-scope">华东库存组织 · ERP / WMS 库存对账</div><div class="recon-filters"><label>对账结果<select aria-label="对账结果"><option value="diff">仅看差异（2）</option><option value="all">全部记录（128）</option></select></label><label>物料 / 交易参考<input aria-label="物料或交易参考" placeholder="输入物料、仓库或交易参考"></label><button data-query>查询</button><button data-reset>重置</button></div><div class="recon-grid" data-detail-grid></div><div class="recon-status"><span data-count></span><div><button data-prev>上一页</button><button data-next>下一页</button></div></div>';let p=0;const draw=()=>{const q=pane.querySelector('input').value.trim().toLowerCase(),only=pane.querySelector('select').value==='diff',list=rows.filter(r=>(!only||r[5]!==r[6])&&r.join(' ').toLowerCase().includes(q));p=Math.max(0,Math.min(p,Math.max(0,Math.ceil(list.length/15)-1)));pane.querySelector('[data-detail-grid]').innerHTML='<table class="recon-business-table" aria-label="ERP与WMS库存对账明细"><thead><tr>'+['交易参考','物料 / 仓库','ERP数量','WMS数量','数量差异','对账结果'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+list.slice(p*15,p*15+15).map(r=>'<tr><td>'+safe(r[0])+'</td><td><strong>'+safe(r[1])+'</strong><small>'+safe(r[2]+' · '+r[3])+'</small></td><td>'+r[5]+'</td><td>'+r[6]+'</td><td>'+(r[6]-r[5])+'</td><td class="'+(r[5]===r[6]?'recon-normal':'recon-error')+'">'+(r[5]===r[6]?'一致':'数量不一致')+'</td></tr>').join('')+'</tbody></table>';pane.querySelector('[data-count]').textContent='共 '+list.length+' 项 · 第 '+(p+1)+' / '+Math.max(1,Math.ceil(list.length/15))+' 页';pane.querySelector('[data-prev]').disabled=p===0;pane.querySelector('[data-next]').disabled=(p+1)*15>=list.length};pane.querySelector('select').onchange=()=>{p=0;draw()};pane.querySelector('input').oninput=()=>{p=0;draw()};pane.querySelector('[data-query]').onclick=()=>{p=0;draw()};pane.querySelector('[data-reset]').onclick=()=>{pane.querySelector('input').value='';pane.querySelector('select').value='diff';p=0;draw()};pane.querySelector('[data-prev]').onclick=()=>{p--;draw()};pane.querySelector('[data-next]').onclick=()=>{p++;draw()};draw()}
function open(kind){close();document.querySelector('.stock-business-pane')?.remove();document.getElementById('query-result-pane')?.remove();document.getElementById('query-pane-divider')?.remove();document.body.classList.remove('ai-has-result','ai-result-expanded');mode=kind;sheet='diff';page=0;document.body.classList.add('reconciliation-open');pane=document.createElement('aside');pane.className='reconciliation-pane';pane.setAttribute('aria-label',kind==='excel'?'库存对账在线Excel':'库存对账业务明细');pane.innerHTML='<header><h2>'+(kind==='excel'?'ERP与WMS库存对账.xlsx':'库存交易对账明细')+'</h2>'+(kind==='excel'?'<a href="inventory-reconciliation.xlsx" download="ERP与WMS库存对账.xlsx">下载 Excel</a>':'')+'<button data-full aria-label="放大页面">放大</button><button data-close aria-label="关闭对账页面">×</button></header><div class="recon-content"></div>';divider=document.createElement('div');divider.className='reconciliation-divider';divider.setAttribute('role','separator');divider.setAttribute('tabindex','0');divider.setAttribute('aria-label','调整对话区与对账页面宽度');divider.innerHTML='<span></span>';main.append(divider,pane);pane.querySelector('[data-close]').onclick=close;pane.querySelector('[data-full]').onclick=()=>{const full=document.body.classList.toggle('reconciliation-expanded');pane.querySelector('[data-full]').textContent=full?'还原':'放大'};divider.onpointerdown=e=>{divider.setPointerCapture(e.pointerId);divider.onpointermove=event=>{const rect=main.getBoundingClientRect(),left=Math.max(0,Math.min(rect.width,event.clientX-rect.left));if(left<rect.width/3){document.body.classList.add('reconciliation-expanded');pane.querySelector('[data-full]').textContent='还原'}else{document.body.classList.remove('reconciliation-expanded');main.style.setProperty('--recon-panel-width',Math.max(360,rect.width-left)+'px')}};divider.onpointerup=()=>divider.onpointermove=null;divider.onpointercancel=()=>divider.onpointermove=null};kind==='excel'?excel():details()}
window.openInventoryReconciliationPane=open;
const original=openInventoryComparison;openInventoryComparison=function(...args){original(...args);const result=document.querySelector('.inventory-chat-result')||document.querySelector('[data-inventory-choice]')?.parentElement;if(!result||result.querySelector('.inventory-result-actions'))return;const actions=document.createElement('div');actions.className='inventory-result-actions';actions.innerHTML='<button type="button" data-excel>▦ 导出 Excel</button><button type="button" data-detail>查看对账明细 ↗</button>';result.append(actions);actions.querySelector('[data-excel]').onclick=()=>open('excel');actions.querySelector('[data-detail]').onclick=()=>open('details')};
for(const key of ['openNewConversation','openActivityBoard','openSkillMarket','openAutomationTasks','openMySpace','openIMSettings','showRoleSelection']){const base=window[key];if(typeof base==='function')window[key]=function(...args){close();return base.apply(this,args)}}
})();
